/// <summary>
/// PricingAttribute of table <c>WHSCustTable</c> field FulfillmentPolicy.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeWHSCustTableFulfillmentPolicy extends UPSPricingAttributeWHSCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSCustTable, FulfillmentPolicy);
}

public Set getAllowedValues()
{
    var          ret = new Set(Types::Int64);
    WHSCustTable wHSCustTable;

    while select wHSCustTable
        group by FulfillmentPolicy
    {
        if (! ret.in(wHSCustTable.FulfillmentPolicy))
        {
            ret.add(wHSCustTable.FulfillmentPolicy);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSCustTable, FulfillmentPolicy));
    qbr.value(queryValue(_value));
}
